import{_ as a,o as t,c as s,a5 as o}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Sequence Flow — List Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-10-list-workspace/sequence-flow.md","filePath":"feature/agency-workspace/3-4-10-list-workspace/sequence-flow.md"}'),r={name:"feature/agency-workspace/3-4-10-list-workspace/sequence-flow.md"};function i(n,e,l,c,d,h){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="sequence-flow-—-list-workspace" tabindex="-1">Sequence Flow — List Workspace <a class="header-anchor" href="#sequence-flow-—-list-workspace" aria-label="Permalink to &quot;Sequence Flow — List Workspace&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.10). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly. It does not restate business rules — see <code>spec.md</code> for those. &gt; &gt; Updated: 2026-09-25.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Client</strong> — the signed-in user, a Workspace member of any role (MANAGER, CREATOR, CLIENT).</li><li><strong>System</strong> — the application service handling the request.</li><li><strong>Database</strong> — the persistent store holding Workspace and membership records.</li></ul><hr><h2 id="flow-a-—-workspaces-the-user-belongs-to" tabindex="-1">Flow A — Workspaces the user belongs to <a class="header-anchor" href="#flow-a-—-workspaces-the-user-belongs-to" aria-label="Permalink to &quot;Flow A — Workspaces the user belongs to&quot;">​</a></h2><ol><li>Client → System: open the Workspace list screen (<code>WorkspacePage</code>).</li><li>System → Database: find every Agency the caller owns (<code>agencyRepository.findByOwnerIdAndStatusNot(..., SOFT_DELETED)</code>).</li><li>System → Database: for each owned Agency, load its Workspaces (<code>workspaceRepository.findByAgencyId</code>) and collect their ids.</li><li>System → Database: read the current user&#39;s active membership rows (filtered by user and active flag) and collect their Workspace ids too, merged into the same id set (<code>LinkedHashSet</code>, de-duplicated).</li><li>System → Database: <code>findAllById(workspaceIds)</code> — <strong>no status filter is applied here</strong> (known gap, see spec.md).</li><li>Database → System: the matching Workspace records, including any that are SOFT_DELETED.</li><li>System: map each Workspace to a Workspace summary.</li><li>System → Client: the list of Workspace summaries.</li><li>Client: render the Workspace list — an empty state when the user belongs to none.</li></ol><h2 id="flow-b-—-workspaces-the-user-manages" tabindex="-1">Flow B — Workspaces the user manages <a class="header-anchor" href="#flow-b-—-workspaces-the-user-manages" aria-label="Permalink to &quot;Flow B — Workspaces the user manages&quot;">​</a></h2><ol><li>Client → System: open the &quot;Workspaces I manage&quot; screen.</li><li>System: read the current user&#39;s active memberships and keep only those with the MANAGER role.</li><li>System → Database: load the Workspace records for the remaining identifiers.</li><li>System: count the active members for each of those Workspaces.</li><li>System: map each Workspace to a managed-Workspace summary carrying id, name, role, and member count.</li><li>System → Client: the list of managed Workspace summaries.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>Status</th><th>Error code</th></tr></thead><tbody><tr><td>List (A / B)</td><td>Caller is not signed in</td><td>401</td><td>Shared authentication mechanism — no Workspace-specific error code</td></tr></tbody></table><p>No other business error codes apply: both flows only read data scoped to the current user and contain no 4xx/409 branch.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Flow A merges two sources: Workspaces of any Agency the caller owns, and Workspaces the caller has an active membership in — an Agency Owner sees every Workspace of their Agency even without a membership row.</li><li><strong>Known gap:</strong> <code>findAllById(workspaceIds)</code> in Flow A step 5 has no SOFT_DELETED filter — a soft-deleted Workspace (FR 3.4.15) can still appear in this list. Not fixed here (docs-only).</li><li>The Database access pattern is read-only; neither flow writes anything.</li></ul>',15)])])}const u=a(r,[["render",i]]);export{m as __pageData,u as default};
